sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', outdated: [], summary: {} };
  try {
    var installed = JSON.parse(inputs.installed_data);
    var available = JSON.parse(inputs.available_data);

    var availableMap = {};
    for (var i = 0; i < available.length; i++) {
      availableMap[available[i].sys_id] = available[i];
    }

    var criticalCount = 0;
    var warningCount = 0;

    for (var j = 0; j < installed.length; j++) {
      var plugin = installed[j];
      var update = availableMap[plugin.sys_id];

      if (update && update.available_version !== plugin.version) {
        var currentParts = (plugin.version || '0.0.0').split('.');
        var availParts = (update.available_version || '0.0.0').split('.');

        var majorDiff = (parseInt(availParts[0], 10) || 0) - (parseInt(currentParts[0], 10) || 0);
        var isOutdated = majorDiff > 0 || (parseInt(availParts[1], 10) || 0) > (parseInt(currentParts[1], 10) || 0);

        if (isOutdated) {
          var severity = majorDiff > 0 ? 'critical' : 'warning';
          if (severity === 'critical') criticalCount++;
          else warningCount++;

          result.outdated.push({
            sys_id: plugin.sys_id,
            name: plugin.name,
            current_version: plugin.version,
            available_version: update.available_version,
            severity: severity,
            version_gap: majorDiff + ' major versions behind'
          });
        }
      }
    }

    result.summary = {
      total_outdated: result.outdated.length,
      critical: criticalCount,
      warning: warningCount
    };
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to identify outdated plugins: ' + e.message;
  }
  return result;
})(inputs);
